v(eclipse_sort_2_09, error(type_error(list,[a|b])), (sort([a|b],_))).
v(eclipse_sort_2_10, error(type_error(list,3)), (sort([], 3))).
v(eclipse_sort_2_11, error(type_error(list,[a|b])), (sort([], [a|b]))).
v(lgt_sort_2_12, error(type_error(list,[a,b|c])), (sort([a,b|c],_))).
v(lgt_sort_2_13, error(type_error(list,[a,b,c|d])), (sort([a,b,c], [a,b,c|d]))).
